+import { $internal } from '../common';
+import { isRelation } from '../relation/utils/is-relation';
+import type { Trait, TraitRecord } from '../trait/types';
+import { getTrait } from '../trait/trait';
+import type { World } from '../world';
+
+export const $predicate = Symbol('predicate');
+
+let predicateId = 0;
+
+export type PredicateData<T extends readonly Trait[]> = {
+    [K in keyof T]: T[K] extends Trait ? TraitRecord<T[K]> : never;
+};
+
+export type Predicate<T extends readonly Trait[] = readonly Trait[]> = {
+    readonly [$predicate]: true;
+    readonly id: number;
+    readonly dependencies: T;
+    readonly test: (data: PredicateData<T>) => boolean;
+};
+
+/** Create a value-based entity filter over the supplied trait data. */
+export function createPredicate<T extends readonly Trait[]>(
+    dependencies: T,
+    test: (data: PredicateData<T>) => boolean
+): Predicate<T> {
+    for (const dependency of dependencies) {
+        if (dependency[$internal].type === 'tag') {
+            throw new Error('Koota: Predicates cannot depend on tags.');
+        }
+        if (isRelation(dependency) || dependency[$internal].relation) {
+            throw new Error('Koota: Predicates cannot depend on relations.');
+        }
+    }
+
+    return Object.freeze({
+        [$predicate]: true as const,
+        id: predicateId++,
+        dependencies,
+        test,
+    });
+}
+
+export function isPredicate(value: unknown): value is Predicate {
+    return !!(value as Predicate | undefined)?.[$predicate];
+}
+
+export function matchesPredicate(world: World, entity: number, predicate: Predicate): boolean {
+    const data = new Array(predicate.dependencies.length);
+    for (let i = 0; i < predicate.dependencies.length; i++) {
+        const value = getTrait(world, entity, predicate.dependencies[i]);
+        if (value === undefined) return false;
+        data[i] = value;
+    }
+    return !!predicate.test(data);
+}
