+        const world = createWorld();
+        world.init();
+        const Position = trait({ x: 0 });
+        const Visible = trait();
+        const rightOfOrigin = createPredicate([Position], ([position]) => position.x > 0);
+        const left = world.spawn(Position({ x: -1 }), Visible);
+        const right = world.spawn(Position({ x: 1 }), Visible);
+
